package com.ecommerce.notification.service; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/notifications") public class NotificationController { final NotificationRepository repo; NotificationController(NotificationRepository r){repo=r;} record Req(@NotNull UUID userId,@NotBlank String type,@NotBlank String message){} @PostMapping Notification create(@RequestBody Req x){Notification n=new Notification();n.setUserId(x.userId());n.setType(x.type());n.setMessage(x.message());return repo.save(n);} @GetMapping("/{userId}") List<Notification> list(@PathVariable UUID userId){return repo.findByUserIdOrderByCreatedAtDesc(userId);} @PatchMapping("/{id}/read") Notification read(@PathVariable UUID id){Notification n=repo.findById(id).orElseThrow();n.setReadFlag(true);return repo.save(n);} }